#include <cstdio>
#include <unordered_map>
#define MAX 10000

int main(void) {
    int n, num, max, mnum;
    std::unordered_map<int, int> data;

    for (;;) {
        max = mnum = 0;
        data.clear(); // Clear the map for each new input

        scanf("%d", &n);
        if (n == 0) break;

        for (int i = 0; i < n; i++) {
            int des[2];
            scanf("%d %d %d", &num, &des[1], &des[0]);
            data[num] += des[0] + des[1]; // Accumulate the values directly

            if (data[num] > max) {
                max = data[num];
                mnum = num;
            }
        }

        printf("%d %d\n", mnum, max);
    }

    return 0;
}

