#define MAX 10000

int main(void) {
    int n, max, mnum;
    int data[MAX + 1] = {0}; // efficient array initialization

    while (scanf("%d", &n) == 1 && n != 0) { // combined condition reduces checks
        max = 0;
        mnum = 0;

        for (int i = 0; i < n; i++) {
            int num, des0, des1; // clarity in variable declaration
            if (scanf("%d %d %d", &num, &des1, &des0) == 3) { // error handling for input
                data[num] = des0 + des1; // Store directly in the array

                if (data[num] > max) { // Check for maximum
                    max = data[num];
                    mnum = num;
                }
            }
        }

        printf("%d %d\n", mnum, max);
    }

    return 0;
}

