        int mnum = 0, max = 0;
        for (int i = 1; i <= MAX; i++) { // start from 1 for meaningful index
            if (data[i] > max) {
                max = data[i];
                mnum = i;
            }
        }

        printf("%d %d\n", mnum, max);
    }

    return 0;
}

